pthread_mutex_t data_mtx;
int shared_resource = 0;

// Static Initialization (Common)
// pthread_mutex_t data_mtx = PTHREAD_MUTEX_INITIALIZER;

// Dynamic Initialization
pthread_mutex_init(&data_mtx, NULL);

// Lock
pthread_mutex_lock(&data_mtx);
shared_resource++; // Critical Section
pthread_mutex_unlock(&data_mtx);

// Non-Blocking Lock Attempt
if (pthread_mutex_trylock(&data_mtx) == 0) {
    // success
    pthread_mutex_unlock(&data_mtx);
}

// Cleanup
pthread_mutex_destroy(&data_mtx);
